package com.nametag.domain.match.model; import com.nametag.domain.animal.model.*; import java.util.*; public final class ShelterQuestions {private ShelterQuestions(){} public static List<String> forAnimal(Animal a){List<String> q=new ArrayList<>();if(a.kg()==null)q.add("성견 체중 예상은?");if(a.infoLevel()==InfoLevel.LACKING)q.add("사람과 다른 개에게 어떤가?");if(a.neonate())q.add("부모견 크기는?");q.add("임시보호 경험이 있나?");return q;} }
